import{_ as o,o as t,c as r,ag as n}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"FAQ & Troubleshooting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/05-faq-and-troubleshooting.md","filePath":"en/05-faq-and-troubleshooting.md"}'),a={name:"en/05-faq-and-troubleshooting.md"};function i(s,e,l,d,u,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="faq-troubleshooting-guide" tabindex="-1">FAQ &amp; Troubleshooting Guide <a class="header-anchor" href="#faq-troubleshooting-guide" aria-label="Permalink to &quot;FAQ &amp; Troubleshooting Guide&quot;">​</a></h1><blockquote><p><strong>Frequently Asked Questions, Debugging Tips, and Common Fixes</strong></p></blockquote><hr><h2 id="_1-frequently-asked-questions-faq" tabindex="-1">1. Frequently Asked Questions (FAQ) <a class="header-anchor" href="#_1-frequently-asked-questions-faq" aria-label="Permalink to &quot;1. Frequently Asked Questions (FAQ)&quot;">​</a></h2><h3 id="can-i-run-softforge-without-docker" tabindex="-1">Can I run SoftForge without Docker? <a class="header-anchor" href="#can-i-run-softforge-without-docker" aria-label="Permalink to &quot;Can I run SoftForge without Docker?&quot;">​</a></h3><p><strong>Yes.</strong> During development and prototyping, you can run the API using the Python virtual environment (<code>.venv</code>) and the frontend with <code>npm run dev</code>. Automated integration tests utilize SQLite in-memory, requiring no external databases.</p><h3 id="how-does-dual-authentication-work-cookie-bearer" tabindex="-1">How does dual authentication work (Cookie + Bearer)? <a class="header-anchor" href="#how-does-dual-authentication-work-cookie-bearer" aria-label="Permalink to &quot;How does dual authentication work (Cookie + Bearer)?&quot;">​</a></h3><p>SoftForge accepts JWT tokens either via the <code>Authorization: Bearer &lt;token&gt;</code> header or through a secure <code>HttpOnly</code> cookie named <code>access_token</code>. This guarantees maximum browser security against XSS attacks while remaining fully compatible with external clients, mobile apps, and tools like Postman or cURL.</p><h3 id="golden-rule-why-must-every-feature-be-rigorously-documented" tabindex="-1">Golden Rule: Why must every feature be rigorously documented? <a class="header-anchor" href="#golden-rule-why-must-every-feature-be-rigorously-documented" aria-label="Permalink to &quot;Golden Rule: Why must every feature be rigorously documented?&quot;">​</a></h3><p>SoftForge is designed to be operated and expanded by both human engineers and <strong>Autonomous AI Agents</strong> (Cursor, Antigravity, Claude Code, GitHub Copilot). LLMs rely strictly on code and active documentation in their context windows. <strong>If a feature or architectural decision is undocumented, it does not exist to the AI.</strong> Undocumented changes lead to hallucinations, broken contracts, and redundant code. In SoftForge, documentation evolves continuously alongside implementation in the same pull request or task.</p><hr><h2 id="_2-common-troubleshooting" tabindex="-1">2. Common Troubleshooting <a class="header-anchor" href="#_2-common-troubleshooting" aria-label="Permalink to &quot;2. Common Troubleshooting&quot;">​</a></h2><h3 id="why-does-opening-docs-dist-index-html-via-file-look-unstyled" tabindex="-1">Why does opening <code>docs/dist/index.html</code> via <code>file:///</code> look unstyled? <a class="header-anchor" href="#why-does-opening-docs-dist-index-html-via-file-look-unstyled" aria-label="Permalink to &quot;Why does opening `docs/dist/index.html` via `file:///` look unstyled?&quot;">​</a></h3><ul><li><strong>Cause:</strong> VitePress (and modern static site generators) compiles CSS and JS with absolute root paths (e.g. <code>/assets/style.css</code>). When opened via local <code>file:///</code> paths in Windows Explorer: <ol><li>The leading slash <code>/</code> resolves to your drive root (<code>V:\\assets\\...</code>), triggering 404s for stylesheets and scripts.</li><li>Modern web browsers block ES modules (<code>&lt;script type=&quot;module&quot;&gt;</code>) over <code>file://</code> due to local file CORS security policies.</li></ol></li><li><strong>Solution:</strong><ol><li><strong>Full VitePress Experience (Recommended):</strong> Double-click <code>docs.bat</code> in the repository root (or run <code>.\\docs.ps1</code> in PowerShell). This launches a local static preview server at <code>http://localhost:5174</code> with offline search and theme support.</li><li><strong>Zero-Server Standalone Manual:</strong> Open <code>docs/manual-offline.html</code> directly with a double-click. It is 100% self-contained with inlined CSS and requires no local server.</li></ol></li></ul><h3 id="error-modulenotfounderror-no-module-named-greenlet" tabindex="-1">Error: <code>ModuleNotFoundError: No module named &#39;greenlet&#39;</code> <a class="header-anchor" href="#error-modulenotfounderror-no-module-named-greenlet" aria-label="Permalink to &quot;Error: `ModuleNotFoundError: No module named &#39;greenlet&#39;`&quot;">​</a></h3><ul><li><strong>Cause:</strong> SQLAlchemy 2.0 Async requires <code>greenlet</code> for coroutine dispatch.</li><li><strong>Solution:</strong> Run <code>pip install &quot;greenlet&gt;=3.0.0&quot;</code> in your virtual environment.</li></ul><h3 id="error-port-8000-or-5173-already-in-use" tabindex="-1">Error: <code>Port 8000 or 5173 already in use</code> <a class="header-anchor" href="#error-port-8000-or-5173-already-in-use" aria-label="Permalink to &quot;Error: `Port 8000 or 5173 already in use`&quot;">​</a></h3><ul><li><strong>Cause:</strong> Another process is currently listening on the default API or Vite port.</li><li><strong>Solution:</strong> Adjust <code>API_PORT=8001</code> in your <code>.env</code> or terminate the conflicting process.</li></ul>',18)])])}const m=o(a,[["render",i]]);export{g as __pageData,m as default};
